class stringx
{
  char data_[8];

public:
  stringx();
  stringx(const char *);
  stringx(const stringx &);
  ~stringx();
  const char *c_str() const;
};

stringx operator+(const stringx &, const stringx &);
stringx operator+(const char *, const stringx &);
stringx operator+(const stringx &, const char *);
extern bool file_finder_exists(
  const stringx &, const stringx &, stringx *);
extern void error(const stringx &);

class chunk_file
{
public:
  void open(const stringx &, int);
};

class world_dynamics_system
{
public:
  stringx wds_open(
    chunk_file &, const stringx &, const stringx &, int);
};

stringx world_dynamics_system::wds_open(
  chunk_file &fs, const stringx &filename,
  const stringx &extension, int io_flags)
{
  stringx fname;
  if (file_finder_exists(filename, extension, &fname))
  {
    fs.open(fname, io_flags);
    return fname;
  }
  else
  {
    error("Couldn't open \"" + filename + extension + "\"");
    return stringx();
  }
}
